"""Produce YEE-143 reports from frozen evidence; no market scoring or concepts."""
import argparse
from collections import Counter
import json
from pathlib import Path
import shutil
import xml.etree.ElementTree as ET


def read_rows(path):
    return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines()]


def table(headers, rows):
    def cell(value):
        return str(value).replace("|", "/").replace("\n", " ")
    return "\n".join(["| " + " | ".join(headers) + " |", "| " + " | ".join("---" for _ in headers) + " |"] + ["| " + " | ".join(cell(c) for c in row) + " |" for row in rows]) + "\n"


def tests(path):
    root = ET.parse(path).getroot()
    suites = list(root.iter("testsuite"))
    values = {k: sum(int(s.get(k, 0)) for s in suites) for k in ("tests", "failures", "errors", "skipped")}
    values["non_skipped"] = values["tests"] - values["skipped"]
    values["passed"] = values["tests"] - values["failures"] - values["errors"] - values["skipped"]
    return values


def generate(base, repo, output, head, pr):
    output.mkdir(parents=True, exist_ok=True)
    data = base / "dossier_data"
    sources = {r["source_id"]: r for r in read_rows(data / "SOURCE_DOCUMENTS.jsonl")}
    products = {r["canonical_identity"]: r for r in read_rows(data / "VERIFIED_PRODUCTS.jsonl")}
    profiles = read_rows(data / "DEMAND_POOL_PROFILES.jsonl")
    observations = read_rows(data / "PAID_SIGNAL_EVIDENCE.jsonl")
    verification = read_rows(data / "REVIEW_PRODUCT_FORM_VERIFICATION.jsonl")
    universe = read_rows(data / "COMMERCIAL_SIGNAL_UNIVERSE.jsonl")
    audit = json.loads((base / "INPUT_HASH_AUDIT.json").read_text(encoding="utf-8"))
    qa = json.loads((data / "QA_RESULT.json").read_text(encoding="utf-8"))
    capture = json.loads((repo / "research" / "yee143_capture.json").read_text(encoding="utf-8"))
    def report(name, body):
        (output / (name + ".md")).write_text("# YEE-143 — " + name + "\n\nAs of/retrieved: 2026-10-03. Worker evidence; Supervisor acceptance pending.\n\n" + body + "\n", encoding="utf-8")
    def product_link(identity):
        p = products[identity]
        return "[" + p["title"] + "](" + sources[p["source_id"]]["canonical_url"] + ")"
    report("INPUT_RECONCILIATION", "The accepted inputs were opened read-only and their byte hashes reconciled to downloaded canonical Drive manifests and accepted Linear handoffs. All seven SQLite integrity checks returned `ok`. YEE-61/73 identity sets agree; all 10,018 scoped feature payloads match YEE-29 exactly. No upstream writes.\n\n" + table(["Input", "SQLite SHA-256", "Downloaded manifest SHA-256"], [(r["issue"], r["sha256"], r["manifest_sha256"]) for r in audit]) + "\nYEE-27/28/29 each preserve 169,007 underlying resources/features: Voxel 6,639, Hangar 3,861, Modrinth 158,507. YEE-61 is the authoritative eligible foundation: 10,018 scoped rows (Hangar 3,861, Voxel 6,157), including 1,352 confirmed, 7,233 REVIEW and 1,433 OUT_OF_SCOPE. The 482 Voxel features absent from YEE-61 and the Modrinth superset are outside this WO's accepted foundation; they are not silently re-admitted. This is complete coverage of the accepted universe, not all products on today's internet.\n\nConfirmed: Hangar 1,221; Voxel 131 (52 paid precedent, 79 free-engagement context). No inherited payment counters. Hangar paid/price availability remains unknown. Full native download/freshness percentiles and primary/secondary taxonomy memberships are preserved as context. All 11 categories and 38 subcategories remain in the dossier, including zero-commercial/unknown cells.\n\nRecovery relevance: native paid flag OR positive native price, with no download/review threshold. Exactly 3,232 REVIEW candidates, all retained in the verification table. Twenty locally positively verified; 3,212 stay excluded/unverified. Accepted membership unchanged.\n\nYEE-77 hash is the accepted fixed research database. YEE-81 uses the supervisor-fixed final database, not the earlier worker version. Their old cohort/direction IDs, selection and scores were not imported. Only source-level context was reconciled after current pools formed. YEE-30–59, YEE-24 and YEE-140/141 findings did not seed products or pools. See INPUT_HASH_AUDIT.json and the seven upstream manifests in the package.")
    coverage = []
    for t in read_rows(base / "stage_a" / "TAXONOMY_COVERAGE.jsonl"):
        rows = [r for r in universe if (r.get("membership") or {}).get("primary_category_id") == t["category_id"]]
        coverage.append({"category_id": t["category_id"], "accepted_primary_members": len(rows), "initial_price_paid_precedent": sum(r["initial_evidence_tier"] == "PAID_PRECEDENT_ONLY" for r in rows), "fresh_direct_in_accepted_membership": sum(r["final_evidence_tier"] == "DIRECT_PAID_SIGNAL" for r in rows), "local_buyer_job_pools": sum(p["category_id"] == t["category_id"] for p in profiles)})
    (output / "CATEGORY_COVERAGE.jsonl").write_text("".join(json.dumps(r, sort_keys=True) + "\n" for r in coverage), encoding="utf-8")
    report("COMMERCIAL_SIGNAL_UNIVERSE", "Stage A froze the candidate universe before public research. It includes all 1,352 confirmed rows and a separate 3,232-row recovery queue; the full 10,018-row scope audit also retains excluded rows. Engagement never becomes a payment proxy. Each original feature, price/currency, native metric, timestamp, snapshot path and accepted category is preserved.\n\nFinal locally eligible universe: 1,372 rows. Evidence tiers: " + str(dict(Counter(r["final_evidence_tier"] for r in universe))) + ". The 51 price/paid precedents without direct payments are not evidence-backed demand. Their current traction is unresolved; pool names cannot be invented from titles.\n\n" + table(["Accepted primary category", "Rows", "Initial paid precedent", "Fresh direct in accepted membership", "Local buyer-job pools"], [(r["category_id"], r["accepted_primary_members"], r["initial_price_paid_precedent"], r["fresh_direct_in_accepted_membership"], r["local_buyer_job_pools"]) for r in coverage]) + "\nLocal recovered products have no accepted YEE-61 primary membership; buyer-job crosswalks are explicitly local. Twenty-two canonical products received fresh form/identity verification (two already confirmed, twenty recovered), plus three separate external corroboration/offer records. External products do not expand accepted membership. No category with missing direct evidence is declared commercially empty. See stage_a/COMMERCIAL_SIGNAL_UNIVERSE.jsonl for the before-research boundary and normalized output for the final tier per row.")
    recovered = [r for r in verification if r["verification_state"] == "VERIFIED_SERVER_PROXY_PLUGIN"]
    report("REVIEW_PRODUCT_FORM_VERIFICATION", "Every one of the 3,232 commercial REVIEW candidates is represented. Default exclusion remains until an opened primary source positively establishes a Minecraft server/proxy plugin and current identity. Twenty pass locally; 3,212 remain EXCLUDED_UNVERIFIED. A review queue is not proof of eligibility or of buyer payment. Unvisited and inaccessible rows are explicitly unresolved, not rejected demand.\n\n" + table(["Canonical row", "Current product/source", "Positive form basis"], [(r["canonical_identity"], product_link(r["canonical_identity"]), r["positive_product_form_evidence"]) for r in recovered]) + "\nThe six additional considered exclusions are explained in `fresh_verification_note`: Lands, MMOItems, ExcellentShop configuration, CarbonSpigot, NullCordX and cosmetic wings. No current counter from the true NightExpress ExcellentShop was assigned to Rafalll's configuration. Native ItemsAdder voxel:1851 is OUT_OF_SCOPE; its contradictory opened current plugin description is parked in the source ledger and excluded from synthesis. No marketplace alias bypass.\n\nRecovery is bounded fresh validation, not a census of all commercial REVIEW rows. Initial native prices identify the queue; after direct counters/buyer statements surfaced, verification followed those observed payments and their buyer jobs. Downloads were retained as context, never used to claim paid traction. Plugin editions of mixed-platform projects are explicitly separated from Fabric/Forge/mod artifacts; configurations/models/builds remain excluded.")
    direct = [o for o in observations if o["kind"] == "public_purchase_counter"]
    report("PAID_SIGNAL_EVIDENCE", "Fresh normalized observations: 22 product-labelled public purchase counters, 7 explicit self-reported purchase channels, 23 price-only observations and 1 tentative purchase intent. These are observation types, not buyer totals. The six diary purchases share one actor; the mcMMO author-page comments are retained as one conservative historical channel. Anonymous statements are not receipt audits.\n\n" + table(["Product", "Canonical identity", "Displayed Purchases", "Displayed price", "Displayed update", "Support display"], [(product_link(o["canonical_identity"]), o["canonical_identity"], o["value"], str(sources[o["source_id"]]["facts"]["price_display_amount"]) + " " + sources[o["source_id"]]["facts"]["currency_display"], sources[o["source_id"]]["facts"]["updated_display"], sources[o["source_id"]].get("support_duration_display", "UNKNOWN")) for o in direct]) + "\nCounters are the main product's Purchases block, not recommended-product counters. Each records source URL, retrieval day, label and limitations. Distinct customers, refunds, free grants, transferred licenses, bundles and sales time windows are unknown. No counters are summed. No conversion to revenue, WTP, market size or currency ranking. Some opened pages were tool-cached up to a month: these are displayed observations, not real-time audits.\n\nDisplayed Standard EULA/support terms were re-opened for all 22 counter-bearing products; most say Lifetime support, AquaticCrates says 1 year. These are offers, not verification of legal rights or future support performance. Source ledger retains current claims versus older buyer complaints. mcMMO numeric current price and EconomyShopGUI Premium numeric current price are unknown. AdvancedJobs EUR17.99 is paid precedent only; ChatControl/VelocityControl intent remains tentative.\n\nExplicit buyer evidence: [purchase diary](" + sources["buyer_diary"]["canonical_url"] + "), [mcMMO member comments](" + sources["buyer_mcmmo"]["canonical_url"] + "), [current tentative chat intent](" + sources["buyer_chat_intent"]["canonical_url"] + "). Each assertion is linked by observation/source IDs in JSONL. Negative reviews alone never become payments unless they explicitly state buying/paying; no review-count conversion.")
    sections = []
    for p in profiles:
        members = ", ".join(product_link(i) + " (`" + i + "`)" for i in p["products"])
        witness = p["independent_corroboration"]
        sections.append("## " + p["buyer_job"] + "\n\n`" + p["pool_id"] + "` — " + p["evidence_state"] + ". Local taxonomy: " + p["category_id"] + "/" + p["subcategory_id"] + ".\n\nProducts: " + members + ".\n\nDirect products/observations/vendors: " + str(p["paid_signal_products"]) + "/" + str(p["paid_signal_observations"]) + "/" + str(p["vendor_count"]) + "; source domains: " + ", ".join(p["source_domains"]) + ". Corroboration: " + (json.dumps(witness) if witness else "insufficient independent paid corroboration") + ".\n\n" + p["assessment"] + " Concentration: " + p["concentration_risk"] + ". Free/context IDs: " + ", ".join(p["free_context_source_ids"]) + ". Maintenance dates, exact observation IDs, buyer channels and licensing are in the machine profile/source rows. Current functionality, reliability and support quality are vendor claims or individual reports, not runtime-validated conclusions. Advancement fields: null.")
    report("DEMAND_POOL_PROFILES", "Eighteen operator outcomes were formed after paid observations. Eight have an explicit independent witness; ten remain single-source/concentrated. Descriptive dimensions, not a global rank. Every pool has an accepted or locally recovered canonical anchor. Different jobs (shops, currency, wages, skills, crop farming, fishing, cosmetics, name presentation) are preserved separately. No product is mechanically duplicated across jobs.\n\n" + "\n\n".join(sections) + "\n\nAcross all pools, paying-customer uniqueness, refunds, current purchase frequency, representative buyer motives, comparative runtime reliability and a defensible new-product wedge remain unknown. Evidence-backed demand describes existing paid behavior, not unmet demand or authorization for concepts.")
    context = read_rows(data / "FREE_INCUMBENT_CONTEXT.jsonl")
    report("FREE_INCUMBENT_CONTEXT", "Substitutes were consulted only after commercial observations for the corresponding jobs. A free alternative does not erase demonstrated payment. Open-source/self-build is distinguished from a verified zero-price binary; undocumented price is UNKNOWN. Base-platform context is not another eligible plugin. Mixed-platform repositories are restricted to their server plugin edition. No equivalence benchmark or implementation recommendation.\n\n" + table(["Pool", "Source/form", "Context and limits"], [(c["pool_id"], "[" + c["source_id"] + "](" + sources[c["source_id"]]["canonical_url"] + ") / " + c["form"], c["context"]) for c in context]) + "\nExcellentEnchants/ExcellentCrates documentation establishes credible functionality but not their current binary price; they are not counted as verified free supply. EssentialsX, spark, TAB, active SimpleClans, AuraSkills, Terra plugin route and source-build routes provide context with explicit source/form constraints. Self-build convenience and vendor support may explain offers; buyer motive prevalence is not established.")
    report("SUPERVISOR_DECISION_BRIEF", "The complete accepted universe has been scanned; a narrow fresh evidence dossier is ready for review. Existing paid behavior appears in eight independently corroborated jobs and ten concentrated jobs. This does not establish whitespace or a viable new paid product. No pool selected; all advancement decisions remain null.\n\n" + table(["Buyer job", "Evidence state", "Paid products/vendors", "Corroboration", "Advance decision"], [(p["buyer_job"], p["evidence_state"], str(p["paid_signal_products"]) + "/" + str(p["vendor_count"]), p["independent_corroboration"]["basis"] if p["independent_corroboration"] else "Insufficient independent confirmation", "null") for p in profiles]) + "\nSupervisor attention: single-vendor crop/fishing/chat pools use independent historical self-reports, not multiple competing vendors; diary evidence is correlated across pools. Exploit protection has distinct vendors but one marketplace counter channel. AquaticCrates reviews allege abandonment/nonworking rewrite; EcoCrates/AdvancedEnchantments support complaints remain unresolved. Free source builds and credible plugin substitutes create pressure without negating actual payment. Current support/compatibility effectiveness is untested.\n\nCoverage: 20 recovered of 3,232 commercial REVIEW candidates; 3,212 remain explicit UNKNOWN eligibility/payment. Fifty-one eligible paid/price precedents have no direct observation. Missing source access and the ItemsAdder OUT_OF_SCOPE contradiction are recorded. No broad negative-demand conclusion or global winner.\n\nQA: normalization and deterministic replay PASS; focused 30/30 PASS; full suite has the same pre-existing missing YEE-95 document failure as baseline. Supervisor may evaluate these limits and future advancement; YEE-143 does not authorize the next WO.")
    evidence = {"focused": tests(base / "focused-final.xml"), "full": tests(base / "full-final.xml"), "baseline": tests(base / "baseline-py312.xml")}
    evidence.update(wheel_build="PASS", syntax_compile="PASS", diff_check="PASS", new_test_warnings=0, lint="No configured repository lint/static runner; not claimed", minecraft_runtime="N/A: analysis-only WO, no runtime plugin/support changes")
    (output / "TEST_EVIDENCE.json").write_text(json.dumps(evidence, sort_keys=True, indent=2) + "\n", encoding="utf-8")
    report("FINAL_REPORT", "Completed authorized demand-first research and normalization; supervisor acceptance pending. No Product Spec, concepts, pricing recommendation, plugin implementation or subsequent WO.\n\nBaseline: `19fbfac376d836951c52db15b8e0a0d694937c58`. Final code HEAD: `" + head + "`. [GitHub PR](" + pr + ") OPEN/UNMERGED. Dedicated branch `codex/yee-143-demand-first-commercial-reset`. No collector behavior changes, integrations, migrations or support matrix expansion.\n\nMethod: verify accepted manifests and read-only hashes; scan all scope rows and accepted memberships; identify all paid/price REVIEW candidates; freeze Stage A; open public paid/counter/buyer sources; recover only positively proven plugins; group coherent operator jobs; research substitutes afterwards; enforce taxonomy and independence witnesses; replay deterministic outputs. Fresh research comprises 47 retained batches and 48 opened source records. Generic commission payment and free-to-paid migration reports are parked where product/form/job attribution remains unresolved. First seven batch payloads were not fully retained; available source headers and later request payloads are preserved. This limits search-process reconstruction, not the opened-source claim ledger. All facts remain source-linked.\n\nResults: 1,352 accepted rows; 3,232 recovery candidates; 20 positive local recoveries; 3,212 exclusions unresolved; 1,372 final eligible rows. Twenty-five fresh verified product records include three separate external context records. Fifty-three normalized observations; eighteen pools (8 EVIDENCE_BACKED_PAID_DEMAND, 10 PAID_SIGNAL_SINGLE_SOURCE). No global scores or sales sums.\n\n" + table(["Verification", "Exact result"], [(k, json.dumps(v)) for k,v in evidence.items()]) + "\nFull-suite failure: accepted YEE-95 test reads absent `YEE95_GOAL_ALIGNMENT.md`; identical baseline/final failure, no additional failures/errors/skips. Default Python 3.11 first caused 5 collection errors in unchanged legacy modules; final required verification uses Python 3.12. Initial no-isolation packaging lacked tooling; final isolated PEP-517 wheel build PASS.\n\nSemantic smoke evidence: actual full scan matched all accepted row feature payloads; wrong product identity/unopened source/no positive form fail closed; prices/downloads/reviews cannot become paid behavior; independent witnesses are explicit; same-vendor products/marketplace aliases do not manufacture independent supply; free context cannot seed demand; foreign keys/integrity PASS; source DB hashes unchanged; replay byte-identical including SQLite. See QA_RESULT, DETERMINISTIC_REPLAY, SCOPE_SCAN_REPLAY and junit files.\n\nLimits: accepted coverage is not a census of all current marketplace products. Fresh validation covers a bounded subset, with explicit unresolved queue. Counters are cached displayed source units with unknown grants/transfers/refunds/customer uniqueness. Anonymous historical buyers are correlated and nonrepresentative. Vendor licensing/support/version claims and negative reports coexist unresolved. Many core runtimes can be self-built; this does not prove why every buyer pays. Native ItemsAdder conflict is parked without bypassing scope. Current willingness to pay for a new plugin remains unestablished.\n\nWorker GOAL_ALIGNMENT: PASS — server/proxy plugin form gates and demand-first boundary preserved. Supervisor GOAL_ALIGNMENT/acceptance: pending, not asserted. Artifact checksums and complete inventory: DELIVERY_MANIFEST.json. Required reports, source/capture/evidence, full frozen/normalized datasets, QA and test evidence are in the linked YEE-143 folder.\n\n`DEMAND_FIRST_COMMERCIAL_SIGNAL_RESET_READY_FOR_SUPERVISOR_REVIEW`")
    for name in ("focused-final.xml", "full-final.xml", "baseline-py312.xml", "baseline-tests.xml", "INPUT_HASH_AUDIT.json", "DETERMINISTIC_REPLAY.json", "SCOPE_SCAN_REPLAY.json"):
        shutil.copy2(base / name, output / name)
    return qa


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    for key in ("base", "repo", "output", "head", "pr"):
        parser.add_argument("--" + key, required=True)
    a = parser.parse_args()
    generate(Path(a.base), Path(a.repo), Path(a.output), a.head, a.pr)
